function save(state,record){let s=D.clone(state),x=D.clone(record);validate(s,x);let before=(s.fixedExpenses||[]).find(r=>r.id===x.id)||null,prior=s.costs.filter(c=>c.fixedExpense===x.id);if(before&&prior.length&&(before.project!==x.project||(before.frequency||'monthly')!==(x.frequency||'monthly')))throw Error('Esta despesa já possui lançamentos. Cadastre outra para mudar o destino ou tipo.');s.fixedExpenses=(s.fixedExpenses||[]).filter(r=>r.id!==x.id).concat(x);if(x.frequency==='once'){let old=prior[0],cost={...(old||{}),id:old?.id||'fixed:'+x.id+':once',project:x.project,stage:'',category:x.category,supplier:x.supplier,description:x.description,amount:x.amount,incurred:old?.incurred||0,paid:old?.paid||0,paymentDiscount:old?.paymentDiscount||0,paymentAddition:old?.paymentAddition||0,date:old?.date||D.today(),due:x.due,paidDate:old?.paidDate||'',note:x.note||'',fixedExpense:x.id,fixedMonth:x.due.slice(0,7)};if(old&&['paid','incurred','paymentDiscount','paymentAddition'].some(k=>Number(old[k]||0)>0)&&['amount','due','project','category','supplier','description'].some(k=>old[k]!==cost[k]))throw Error('Esta despesa já possui baixa. Corrija o pagamento antes de alterar valores ou vencimento.');D.validateRecord(s,'costs',cost);s.costs=s.costs.filter(c=>c.fixedExpense!==x.id).concat(cost)}validateState(s);s.history.unshift({id:id(),time:new Date().toISOString(),kind:'fixedExpenses',record:x.id,action:before?'Despesa geral atualizada':'Despesa geral cadastrada',before,after:x});return s}
