const sortOptions=[['due','Data de vencimento'],['description','Descrição (A–Z)'],['supplier','Fornecedor (A–Z)'],['amount','Valor'],['project','Destino'],['frequency','Tipo de despesa']];
const SORT_KEY=root.EngefexEnvironment?.storageKey('engefex-fixed-expenses-sort-v1')||'engefex-fixed-expenses-sort-v1';let sorting={key:'due',direction:'asc'},query='',selectedKind='all';
try{const saved=JSON.parse(localStorage.getItem(SORT_KEY)||'null');if(sortOptions.some(([key])=>key===saved?.key)&&['asc','desc'].includes(saved.direction))sorting=saved}catch{}
const normalize=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR');
