function expenseDue(x,competence=month){if(x.frequency==='once')return x.due||'';if(!validMonth(competence))return '';const last=Number(D.addDays(D.addMonths(competence+'-01',1),-1).slice(8));return competence+'-'+String(Math.min(x.day,last)).padStart(2,'0')}
