 const compare=(a,b)=>String(a??'').localeCompare(String(b??''),'pt-BR',{numeric:true,sensitivity:'base'}),value=x=>key==='due'?expenseDue(x,competence):key==='project'?destinationName(s,x):key==='frequency'?(x.frequency==='once'?'Única':'Recorrente'):key==='amount'?Number(x.amount)||0:x[key]||'';
