function displayRows(s,project='all',options={}){const text=normalize(options.query??query),kind=options.kind??selectedKind;return sortRows(s,(s.fixedExpenses||[]).filter(x=>!x.deletedAt&&(project==='all'||x.project===project)&&(kind==='all'||(x.frequency||'monthly')===kind)&&(!text||normalize([x.description,x.supplier,x.category,destinationName(s,x)].join(' ')).includes(text))),options.key??sorting.key,options.direction??sorting.direction,options.competence??month)}
