 if(direction)direction.onclick=()=>{sorting.direction=sorting.direction==='asc'?'desc':'asc';saveSort()};
 if(search)search.oninput=()=>{clearTimeout(bind.searchTimer);const position=search.selectionStart;bind.searchTimer=setTimeout(()=>{query=search.value;api.render();const input=$('#fixedSearch');input?.focus();input?.setSelectionRange(position,position)},180)};
